import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;
    static List<Long>[] groups = new ArrayList[9];
    static long[] bit_count = new long[1 << 9];
    static long[] p_values = new long[9];
    static long[] a_values = new long[9];
    static Map<Long, Long>[] state_dp = new HashMap[8];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int n_input = Integer.parseInt(br.readLine());
        for (int i = 0; i < 9; i++) {
            groups[i] = new ArrayList<>();
        }

        for (int i_idx = 0; i_idx < (1 << n_input); i_idx++) {
            int j_idx = Integer.bitCount(i_idx);
            bit_count[i_idx] = groups[j_idx].size();
            groups[j_idx].add((long) i_idx);
        }

        for (int i = 0; i < 8; i++) {
            state_dp[i] = new HashMap<>();
        }

        state_dp[0].put(1L, 1L);

        for (int i_idx = 0; i_idx < n_input; i_idx++) {
            st = new StringTokenizer(br.readLine());
            for (int j_idx = 0; j_idx < n_input; j_idx++) {
                long p = Long.parseLong(st.nextToken());
                p_values[j_idx] = p * 570000004L % MOD;
            }

            Map<Long, Long> currentMap = state_dp[i_idx];
            for (Map.Entry<Long, Long> entry : currentMap.entrySet()) {
                long key = entry.getKey();
                long value = entry.getValue();

                Arrays.fill(a_values, 0);
                for (long m : groups[i_idx]) {
                    if (((key >> bit_count[(int) m]) & 1) != 0) {
                        for (int j_idx = 0; j_idx < n_input; j_idx++) {
                            if (((m >> j_idx) & 1) == 0) {
                                a_values[j_idx] |= (1L << bit_count[(m | (1L << j_idx))]);
                            }
                        }
                    }
                }

                for (int mask = 0; mask < (1 << n_input); mask++) {
                    long X_val = 1;
                    long M_val = 0;
                    for (int j_idx = 0; j_idx < n_input; j_idx++) {
                        if (((mask >> j_idx) & 1) != 0) {
                            M_val |= a_values[j_idx];
                            X_val = (X_val * p_values[j_idx]) % MOD;
                        } else {
                            X_val = (X_val * (MOD + 1 - p_values[j_idx]) % MOD) % MOD;
                        }
                    }
                    long nextCount = state_dp[i_idx + 1].getOrDefault(M_val, 0L);
                    long newVal = (value * X_val) % MOD;
                    state_dp[i_idx + 1].put(M_val, (nextCount + newVal) % MOD);
                }
            }
        }

        System.out.println(state_dp[n_input].getOrDefault(1L, 0L));
    }
}
